GridVisualizerTemplate.ev.EditingChanged-eval:
{
          self.editorRows.Clear();
          if (self.Editing)
          {
            self.editorRows.Add(self.Row);
            GuiApplication::GetApplication().InvokeInMainThread(self.RelatedControlHost, func() : void
            {
              if (self.Editing and editorItems.StackItems.Count != 0)
              {
